package com.InnovaServe.expense.repository;import com.InnovaServe.expense.entity.RecurringExpense;import org.springframework.data.jpa.repository.JpaRepository;import java.time.LocalDate;import java.util.*;
public interface RecurringExpenseRepository extends JpaRepository<RecurringExpense,UUID>{List<RecurringExpense> findAllByTenantIdAndNextDueDateLessThanEqualOrderByNextDueDate(UUID t,LocalDate date);Optional<RecurringExpense> findByTenantIdAndId(UUID t,UUID id);}
